
/* AUTO_UPDATE_V20 */
(function(){
  async function checkForAppUpdate(){
    if(!("serviceWorker" in navigator)) return;
    try{
      const reg = await navigator.serviceWorker.register("./sw.js",{updateViaCache:"none"});
      await reg.update();
      if(reg.waiting){
        reg.waiting.postMessage("SKIP_WAITING");
        showAppUpdatedNotice();
      }
      reg.addEventListener("updatefound",function(){
        const worker=reg.installing;
        if(!worker) return;
        worker.addEventListener("statechange",function(){
          if(worker.state==="installed" && navigator.serviceWorker.controller){
            worker.postMessage("SKIP_WAITING");
            showAppUpdatedNotice();
          }
        });
      });
    }catch(e){ console.warn("Atualização automática:",e); }
  }
  function showAppUpdatedNotice(){
    if(document.getElementById("impactoUpdateNotice")) return;
    const el=document.createElement("div");
    el.id="impactoUpdateNotice";
    el.innerHTML='<div class="impacto-update-box"><div class="impacto-update-icon">✓</div><div><strong>Seu aplicativo foi atualizado</strong><p>Por favor, feche e abra-o novamente para entrar as atualizações.</p></div><button id="impactoUpdateClose" type="button">OK</button></div>';
    document.body.appendChild(el);
    document.getElementById("impactoUpdateClose").onclick=()=>el.remove();
  }
  window.addEventListener("load",checkForAppUpdate);
})();

