function changeQty(btn,delta){const input=btn.parentNode.querySelector('input[type="number"]');if(!input)return;let min=Number(input.min||1),max=Number(input.max||999999),v=Math.max(min,Math.min(max,Number(input.value||min)+delta));input.value=v;input.dispatchEvent(new Event('input',{bubbles:true}));}
